function cancellable<T>(generator: Generator<Promise<any>, T, unknown>): [() => void, Promise<T>] {
    let cancel: () => void = () => {};
    const promise = new Promise<T>((resolve, reject) => {
        cancel = () => {
            step(() => generator.throw('Cancelled'));
        };
        function step(fn: () => IteratorResult<Promise<any>, T>) {
            let res: IteratorResult<Promise<any>, T>;
            try {
                res = fn();
            } catch (err) {
                reject(err);
                return;
            }
            if (res.done) {
                resolve(res.value);
                return;
            }
            Promise.resolve(res.value).then(
                val => step(() => generator.next(val)),
                err => step(() => generator.throw(err))
            );
        }
        step(() => generator.next());
    });
    return [cancel, promise];
}
